from calendar import monthrange
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    origin = date.fromisoformat(start)
    parts = rule.split()
    frequency = parts[0]
    step = int(parts[1])
    result = []

    if frequency == "DAILY":
        return [
            (origin + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    weekdays = {
        code: i
        for i, code in enumerate(("MO", "TU", "WE", "TH", "FR", "SA", "SU"))
    }

    if frequency == "WEEKLY":
        selected = sorted(weekdays[code] for code in parts[2].split(","))
        monday = origin - timedelta(days=origin.weekday())

        while True:
            for weekday in selected:
                candidate = monday + timedelta(days=weekday)
                if candidate >= origin:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=step)

    if frequency == "MONTHLY":
        number = int(parts[2])
        weekday = weekdays[parts[3]] if len(parts) == 4 else None
        month_index = origin.year * 12 + origin.month - 1

        while True:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, days_in_month = monthrange(year, month)

            if weekday is None:
                day = days_in_month if number == -1 else number
            elif number == -1:
                last_weekday = (first_weekday + days_in_month - 1) % 7
                day = days_in_month - (last_weekday - weekday) % 7
            else:
                day = 1 + (weekday - first_weekday) % 7 + 7 * (number - 1)

            if day <= days_in_month:
                candidate = date(year, month, day)
                if candidate >= origin:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result

            month_index += step

    if frequency == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = origin.year

        while True:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= origin:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            year += step
